{"role": "G", "goal": "integration of diverse archived transformations; evaluate the full program", "experiment": "873f902b4e9c4cd7-h01", "ordinal": 2, "integration_source_ids": ["fd41c25e396b42c2"], "current_source_paths": ["src/launch.json", "src/nbody_kernel.cu"], "context_as_data": {"sources": [{"id": "fd41c25e396b42c2", "role": "G", "commit": "1ec283ca77208862916cb989cbadf44500c2d7fc", "transformations": {"files": ["src/nbody_kernel.cu"], "retained": ["Retain warp-level source broadcast, complete-tile and tail handling, and target validity guards from the measured base.", "Use rsqrtf with two Newton refinements to form the inverse distance cubed in both interaction paths, replacing sqrtf and division.", "Preserve the target-mass force accumulation, self-interaction exclusion, integration order, particle layout, and launch configuration."]}, "mean_seconds": 0.000687351400536535, "diff": "diff --git a/src/nbody_kernel.cu b/src/nbody_kernel.cu
index ae1b7ed..e1c1d93 100644
--- a/src/nbody_kernel.cu
+++ b/src/nbody_kernel.cu
@@ -1,52 +1,122 @@
-// Structure "Array of Structures" (AoS) : intuitive mais naïve sur GPU
-// car elle empêche la coalescence parfaite des accès mémoire.
 struct Particle {
     float x, y, z;
     float vx, vy, vz;
     float mass;
 };

-// Kernel CUDA naïf : Simulation gravitationnelle N-Corps (N-Body)
+__device__ __forceinline__ float inverseDistanceCubed(float distSq) {
+    float invDist = rsqrtf(distSq);
+    const float halfDistSq = 0.5f * distSq;
+    invDist *= 1.5f - halfDistSq * invDist * invDist;
+    invDist *= 1.5f - halfDistSq * invDist * invDist;
+    return invDist * invDist * invDist;
+}
+
 extern "C" __global__ void nbody_step_naive(const Particle* in, Particle* out, int n, float dt) {
-    int i = blockIdx.x * blockDim.x + threadIdx.x;
-    if (i >= n) return;
+    constexpr int warpWidth = 32;
+    const unsigned int warpMask = 0xffffffffu;
+    const long long particleCount = static_cast<long long>(n);
+
+    const long long globalIndex =
+        static_cast<long long>(blockIdx.x) * static_cast<long long>(blockDim.x) +
+        static_cast<long long>(threadIdx.x);
+    const bool targetValid = globalIndex < particleCount;
+    const int i = targetValid ? static_cast<int>(globalIndex) : 0;
+
+    Particle p;
+    if (targetValid) {
+        p = in[i];
+    }

     const float G = 1.0f;
     const float softening = 0.001f;
-
     float fx = 0.0f;
     float fy = 0.0f;
     float fz = 0.0f;

-    // Approche naïve : chaque thread parcourt toutes les particules en mémoire globale
-    // sans utiliser de mémoire partagée (__shared__) ni mettre in[i] en registre.
-    for (int j = 0; j < n; j++) {
-        if (i == j) continue; // Divergence de branche inutile dans la boucle
+    const int lane = static_cast<int>(threadIdx.x) & (warpWidth - 1);
+    const long long fullTileLimit = (particleCount / warpWidth) * warpWidth;

-        float dx = in[j].x - in[i].x;
-        float dy = in[j].y - in[i].y;
-        float dz = in[j].z - in[i].z;
+    // Full tiles need no per-source bounds checks. Every lane still participates
+    // in all shuffles, including lanes whose target index is outside n.
+    for (long long tileBase = 0; tileBase < fullTileLimit; tileBase += warpWidth) {
+        const long long sourceIndex = tileBase + lane;
+        const Particle& source = in[static_cast<int>(sourceIndex)];
+        const float sourceX = source.x;
+        const float sourceY = source.y;
+        const float sourceZ = source.z;
+        const float sourceMass = source.mass;

-        float distSq = dx * dx + dy * dy + dz * dz + softening;
-        float dist = sqrtf(distSq); // Calcul coûteux (au lieu de rsqrtf)
+        #pragma unroll
+        for (int sourceLane = 0; sourceLane < warpWidth; ++sourceLane) {
+            const long long sourceJ = tileBase + sourceLane;
+            const float xj = __shfl_sync(warpMask, sourceX, sourceLane);
+            const float yj = __shfl_sync(warpMask, sourceY, sourceLane);
+            const float zj = __shfl_sync(warpMask, sourceZ, sourceLane);
+            const float massJ = __shfl_sync(warpMask, sourceMass, sourceLane);

-        float f = (G * in[i].mass * in[j].mass) / (distSq * dist);
+            if (targetValid && i != sourceJ) {
+                const float dx = xj - p.x;
+                const float dy = yj - p.y;
+                const float dz = zj - p.z;
+                const float distSq = dx * dx + dy * dy + dz * dz + softening;
+                const float f = (G * p.mass * massJ) * inverseDistanceCubed(distSq);

-        fx += f * dx;
-        fy += f * dy;
-        fz += f * dz;
+                fx += f * dx;
+                fy += f * dy;
+                fz += f * dz;
+            }
+        }
     }

-    // Intégration d'Euler explicite
-    Particle p = in[i];
-    p.vx += (fx / p.mass) * dt;
-    p.vy += (fy / p.mass) * dt;
-    p.vz += (fz / p.mass) * dt;
+    // The final partial tile has a uniform trip count for every lane in the warp.
+    const long long tailBase = fullTileLimit;
+    if (tailBase < particleCount) {
+        const long long sourceIndex = tailBase + lane;
+        float sourceX = 0.0f;
+        float sourceY = 0.0f;
+        float sourceZ = 0.0f;
+        float sourceMass = 0.0f;

-    p.x += p.vx * dt;
-    p.y += p.vy * dt;
-    p.z += p.vz * dt;
+        if (sourceIndex < particleCount) {
+            const Particle& source = in[static_cast<int>(sourceIndex)];
+            sourceX = source.x;
+            sourceY = source.y;
+            sourceZ = source.z;
+            sourceMass = source.mass;
+        }

-    out[i] = p;
-}
+        const int tailCount = static_cast<int>(particleCount - tailBase);
+        for (int sourceLane = 0; sourceLane < tailCount; ++sourceLane) {
+            const long long sourceJ = tailBase + sourceLane;
+            const float xj = __shfl_sync(warpMask, sourceX, sourceLane);
+            const float yj = __shfl_sync(warpMask, sourceY, sourceLane);
+            const float zj = __shfl_sync(warpMask, sourceZ, sourceLane);
+            const float massJ = __shfl_sync(warpMask, sourceMass, sourceLane);

+            if (targetValid && i != sourceJ) {
+                const float dx = xj - p.x;
+                const float dy = yj - p.y;
+                const float dz = zj - p.z;
+                const float distSq = dx * dx + dy * dy + dz * dz + softening;
+                const float f = (G * p.mass * massJ) * inverseDistanceCubed(distSq);
+
+                fx += f * dx;
+                fy += f * dy;
+                fz += f * dz;
+            }
+        }
+    }
+
+    if (targetValid) {
+        p.vx += (fx / p.mass) * dt;
+        p.vy += (fy / p.mass) * dt;
+        p.vz += (fz / p.mass) * dt;
+
+        p.x += p.vx * dt;
+        p.y += p.vy * dt;
+        p.z += p.vz * dt;
+
+        out[i] = p;
+    }
+}"}], "interactions": [{"sources": ["c15bc6e5094d48bf"], "outcome": {"binary_sha256": "d241279b8f370eb0f1ba3f80560f7d71a7c1248a8ba0c3c1ea44ccbc145731b1", "cache_key": "b6de833026d09e5f7ea905a6c608d386b602246366dd78311ddb984eb397c3bc", "commit": "1ec283ca77208862916cb989cbadf44500c2d7fc", "correct": true, "logs": ["/gpfs/scratch/nimarano/forest-engine-history-776048-0f0f3abd462c4ed28f1dda68d1df769d/results-780691/cuda-nbody/logs/e1/fd41c25e396b42c2/search/attempt-001/build.log", "/gpfs/scratch/nimarano/forest-engine-history-776048-0f0f3abd462c4ed28f1dda68d1df769d/results-780691/cuda-nbody/logs/e1/fd41c25e396b42c2/search/attempt-001/correctness.log", "/gpfs/scratch/nimarano/forest-engine-history-776048-0f0f3abd462c4ed28f1dda68d1df769d/results-780691/cuda-nbody/logs/e1/fd41c25e396b42c2/search/attempt-001/sample-0.log", "/gpfs/scratch/nimarano/forest-engine-history-776048-0f0f3abd462c4ed28f1dda68d1df769d/results-780691/cuda-nbody/logs/e1/fd41c25e396b42c2/search/attempt-001/sample-1.log", "/gpfs/scratch/nimarano/forest-engine-history-776048-0f0f3abd462c4ed28f1dda68d1df769d/results-780691/cuda-nbody/logs/e1/fd41c25e396b42c2/search/attempt-001/sample-2.log"], "mean_seconds": 0.000687351400536535, "reason": "", "score": 0.7276754410284452, "status": "valid", "times": [0.000687337547158502, 0.0006874537222694702, 0.000687262932181633], "tree_hash": "d0477ea97e7d155e247475a291a7e9d0b902ccdf"}}], "automatic_observations": {"baseline": {"experiment_id": "baseline-e1", "outcome": {"binary_sha256": "116f965b94a3406cf8e44ed742165950fe175dcafe6ae8cc0f1345fe223eb27b", "cache_key": "81e27fdbc124dc8da010302ddda42545613b50adca988bf76ea8f4ecd9d5d0a0", "commit": "2718921299cf73709e9fd8c246989bea4af9f725", "correct": true, "logs": ["/gpfs/scratch/nimarano/forest-engine-history-776048-0f0f3abd462c4ed28f1dda68d1df769d/results-780691/cuda-nbody/logs/e1/baseline-e1/search/attempt-001/build.log", "/gpfs/scratch/nimarano/forest-engine-history-776048-0f0f3abd462c4ed28f1dda68d1df769d/results-780